import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from ml import *
tee('m33'); reset()
n = Node('m33'); n.start(); c = n.client(); db = c.test
N = 200000
fill(db.t, N, lambda i: {'_id': i, 'k': i, 'u': f'user{i}', 'pad': 'x' * 20})
db.t.create_index([('k', 'hashed')]); db.t.create_index('k', name='k_range')
db.t.create_index([('u', 'hashed')])
print('== 一:哈希索引存的不是字段值,而是值的 64 位哈希;mongosh 里用 convertShardKeyToHashed 能算出同样的哈希')
msh(n, 'db.t.getIndexes().filter(i => i.key.k == "hashed" || i.key.u == "hashed").map(i => ({name: i.name, key: i.key}))')
msh(n, '[1, 2, 3, 4, 5].map(v => v + " → " + convertShardKeyToHashed(v))')
msh(n, '["user1", "user2"].map(v => v + " → " + convertShardKeyToHashed(v))')
print('== 二:等值查询走哈希索引:索引范围是 [hash, hash] 一个点;$in 是多个点')
msh(n, EXJS + 'ex(db.t.find({k: 12345}).hint("k_hashed").explain("executionStats"))', label='db.t.find({k: 12345}).hint("k_hashed")', n=12)
msh(n, 'var e = db.t.find({k: 12345}).hint("k_hashed").explain(); var s = e.queryPlanner.winningPlan; while (s.inputStage) s = s.inputStage; JSON.stringify(s.indexBounds)', note='indexBounds')
msh(n, 'var e = db.t.find({k: {$in: [1, 2, 3]}}).hint("k_hashed").explain(); var s = e.queryPlanner.winningPlan; while (s.inputStage) s = s.inputStage; JSON.stringify(s.indexBounds)', note='$in: [1, 2, 3] 的 indexBounds')
print('== 三:范围查询用不了哈希索引:哈希把相邻的值打散了。{k: {$gte: 1000, $lt: 1100}} 强制 hint 哈希索引 vs 普通索引')
msh(n, EXJS + 'ex(db.t.find({k: {$gte: 1000, $lt: 1100}}).hint("k_hashed").explain("executionStats"))', label='hint("k_hashed") 的范围查询', n=12)
msh(n, EXJS + 'ex(db.t.find({k: {$gte: 1000, $lt: 1100}}).hint("k_range").explain("executionStats"))', label='hint("k_range") 的同一个范围查询', n=12)
msh(n, EXJS + 'db.t.dropIndex("k_range"); ex(db.t.find({k: {$gte: 1000, $lt: 1100}}).explain("executionStats"))', label='删掉普通索引后不 hint', n=12)
msh(n, EXJS + 'ex(db.t.find({}).sort({k: 1}).limit(5).hint("k_hashed").explain("executionStats"))', label='sort({k: 1}) 用哈希索引', n=12)
print('== 四:哈希索引上的限制:不能 unique、不能给数组字段建、不能有两个哈希字段(复合索引里只能有一个)')
msh(n, 'try { db.t.createIndex({k: "hashed"}, {unique: true, name: "x"}) } catch (e) { e.message.replace(/^.*caused by :: /, "").slice(0, 150) }', label='createIndex({k: "hashed"}, {unique: true})')
msh(n, 'db.arr.insertOne({_id: 1, k: [1, 2]}); try { db.arr.createIndex({k: "hashed"}) } catch (e) { e.message.replace(/^.*caused by :: /, "").slice(0, 160) }', label='数组字段上建哈希索引')
msh(n, 'try { db.t.createIndex({a: "hashed", b: "hashed"}) } catch (e) { e.message.replace(/^.*caused by :: /, "").slice(0, 160) }', label='createIndex({a: "hashed", b: "hashed"})')
msh(n, 'try { db.t.createIndex({a: 1, b: "hashed"}, {name: "ab"}) } catch (e) { e.message.slice(0, 160) }', label='createIndex({a: 1, b: "hashed"})    // 只有一个哈希字段的复合索引')
print('== 五:哈希会把浮点数截断成 64 位整数再哈希:2.1、2.3 的哈希相同——查询结果仍然正确,但索引里会多检查')
msh(n, '[2.1, 2.3, 2.9, 3].map(v => v + " → " + convertShardKeyToHashed(v))')
db.f.create_index([('x', 'hashed')]); db.f.insert_many([{'_id': 1, 'x': 2.1}, {'_id': 2, 'x': 2.3}, {'_id': 3, 'x': 2.9}, {'_id': 4, 'x': 3}])
msh(n, EXJS + 'ex(db.f.find({x: 2.3}).hint("x_hashed").explain("executionStats"))', label='db.f.find({x: 2.3}).hint("x_hashed")    // 键里同一个哈希有 3 条', n=12)
msh(n, 'db.f.find({x: 2.3}).hint("x_hashed").toArray().map(d => d._id)', label='结果仍然只有 x = 2.3 的文档')
print('== 六:哈希值的分布:连续的整数哈希后均匀分散到整个 64 位空间(这是用它做分片键的原因)')
msh(n, 'db.t.aggregate([{$match: {_id: {$lt: 3}}}, {$project: {_id: 0, k: 1, h: {$toHashedIndexKey: "$k"}}}])', note='聚合里的 $toHashedIndexKey 算出的值与 convertShardKeyToHashed 一致')
hs = [int(d['h']) for d in db.t.aggregate([{'$match': {'_id': {'$lt': 4000}}}, {'$sort': {'_id': 1}}, {'$project': {'_id': 0, 'h': {'$toHashedIndexKey': '$k'}}}])]
print(f'  前 8 个连续整数 0..7 的哈希的符号与量级: {[("-" if h < 0 else "+") + "%.1fe18" % (abs(h) / 1e18) for h in hs[:8]]}')
bins = [0] * 8
for h in hs: bins[min(7, (h + 2 ** 63) * 8 // 2 ** 64)] += 1
print(f'  4000 个连续整数的哈希落在 8 等分的 64 位空间里的个数: {bins}(期望每份 500)')
n.stop()
